package com.sobrenaturaldirector.mutation.safety;
import java.util.*;import com.sobrenaturaldirector.mutation.model.ExecutionReadiness;
public final class MutationSafetyAssessment {public enum Status{SAFE_IN_ABSTRACT_MODEL,REQUIRES_RUNTIME_VALIDATION,BLOCKED,INVALID}private final Status status;private final ExecutionReadiness readiness;private final Set<String> requirements;private final List<String>warnings;public MutationSafetyAssessment(Status status,ExecutionReadiness readiness,Collection<String>requirements,Collection<String>warnings){this.status=status;this.readiness=readiness;this.requirements=Collections.unmodifiableSet(new TreeSet<String>(requirements==null?Collections.<String>emptySet():new HashSet<String>(requirements)));this.warnings=Collections.unmodifiableList(new ArrayList<String>(warnings==null?Collections.<String>emptyList():warnings));}public Status getStatus(){return status;}public ExecutionReadiness getReadiness(){return readiness;}public Set<String> getRequirements(){return requirements;}public List<String> getWarnings(){return warnings;}}
